#!/usr/bin/env dotnet
// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// Find earliest Friday the 13th starting from year 1
DateOnly earliest = default;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
                earliest = date;
            break; // found one this year, but keep going for the count
        }
    }
    if (earliest != default) break;
}

// Actually, let's just find the very first one
earliest = default;
for (int year = 1; year <= 9999; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            goto found;
        }
    }
}
found:
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
// The Gregorian calendar repeats every 400 years exactly.
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
EOF
